css:
/* 星图：昼夜双版（:root 为日间基线，[data-reader-theme="night"] 覆盖夜景）；正文区占页高 80%+（蓝图硬约束①） */
:root{
  --sc-bg:#f6f4ef; --sc-fg:#20242e; --sc-dim:#6c7385;
  --sc-gold:#8a6a12; --sc-line:rgba(138,106,18,.28);
}
[data-reader-theme="night"]{
  --sc-bg:#0a0c16; --sc-fg:#e8e6dd; --sc-dim:#8d92a8;
  --sc-gold:#e0bf63; --sc-line:rgba(224,191,99,.30);
}
html,body{margin:0;padding:0;background:var(--sc-bg);color:var(--sc-fg);
  font-family:"Noto Serif CJK SC","Source Han Serif SC",Georgia,serif;
  font-size:var(--md-font-size,18px);line-height:var(--md-line-height,1.9);}
.sc-head{position:relative;display:flex;justify-content:space-between;align-items:baseline;gap:.6em;
  padding:.6em 1.2em .5em;font-size:.74em;letter-spacing:.28em;color:var(--sc-dim);
  background-image:repeating-linear-gradient(90deg,var(--sc-line) 0 1px,transparent 1px 14px);
  background-size:100% 4px;background-position:bottom left;background-repeat:no-repeat;}
.sc-chapter{max-width:68%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.sc-pct{color:var(--sc-gold);letter-spacing:.08em;font-variant-numeric:tabular-nums;}
.sc-band{position:relative;height:7vh;padding:1em 1.2em 0;overflow:hidden;}
.sc-title{position:relative;z-index:1;font-size:1.6em;font-weight:650;letter-spacing:.16em;}
.sc-dial{position:absolute;right:1.4em;top:.55em;width:11vh;height:11vh;border-radius:50%;pointer-events:none;
  background:repeating-conic-gradient(from 0deg,var(--sc-line) 0deg .35deg,transparent .35deg 3deg),
    radial-gradient(circle,transparent 0 58%,var(--sc-line) 58% 59%,transparent 59% 74%,var(--sc-line) 74% 75%,transparent 75%);
  -webkit-mask-image:radial-gradient(circle,#000 0 78%,transparent 80%);mask-image:radial-gradient(circle,#000 0 78%,transparent 80%);}
.sc-dial::after{content:"";position:absolute;inset:34%;border:1px solid var(--sc-gold);border-radius:50%;}
.sc-body{position:relative;padding:.85em 1.2em 0;}
.sc-body .reader-chapter-title{margin:0 0 .75em;font-size:1.34em;font-weight:650;letter-spacing:.05em;}
.sc-body .reader-chapter-title::after{content:"✦";margin-left:.5em;color:var(--sc-gold);font-size:.7em;}
.sc-body .reader-paragraph{margin:0 0 .95em;text-indent:2em;}
.sc-body p{margin:0 0 .95em;}
.sc-body a{color:var(--sc-gold);text-decoration:none;border-bottom:1px solid var(--sc-line);}
.sc-body blockquote{margin:0 0 1.05em;padding:.45em .95em;border-left:2px solid var(--sc-gold);color:var(--sc-dim);}
.sc-body code{background:rgba(127,127,127,.14);padding:.13em .34em;border-radius:3px;}
.sc-body pre{background:rgba(127,127,127,.10);padding:.8em;border-radius:3px;overflow-x:auto;border:1px solid var(--sc-line);}
.sc-body table{width:100%;border-collapse:collapse;}
.sc-body th,.sc-body td{border:1px solid var(--sc-line);padding:.34em .55em;}
.sc-foot{position:relative;display:flex;justify-content:space-between;align-items:center;gap:.8em;
  padding:.4em 1.2em .55em;font-size:.7em;color:var(--sc-dim);font-variant-numeric:tabular-nums;}
.sc-foot-arc{width:2.6em;height:1.1em;border-bottom:1px solid var(--sc-gold);border-radius:0 0 100% 100%;opacity:.8;}
@media (prefers-reduced-motion:reduce){.sc-dial{background-position:0 0;}}
/* ==== 4.16 成套美术：自研 SVG + OFL 字体 + CC0/PD 纹理 ==== */
.sc-band{height:7vh;}
.sc-art{position:absolute;inset:0;width:100%;height:100%;color:var(--sc-gold);pointer-events:none;}
.sc-band .sc-title{position:relative;z-index:2;}
.sc-edge{display:block;width:100%;height:1.6vh;color:var(--sc-gold);}
.sc-footmark{display:block;width:100%;height:2vh;color:var(--sc-gold);}
.sc-tex{position:absolute;inset:0;background-image:url("data:image/webp;base64,");background-size:cover;background-position:center 34%;pointer-events:none;}
.sc-band::after{content:"";position:absolute;left:0;right:0;bottom:0;height:56%;background:linear-gradient(180deg,transparent,var(--sc-bg));pointer-events:none;}
[data-reader-theme="night"] .sc-tex{filter:brightness(0.78) saturate(.9);}
@font-face{font-family:"Share Tech Mono";font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format("woff2");}
.sc-head,.sc-title,.sc-foot,.sc-pct{font-family:"Share Tech Mono","Noto Serif CJK SC","Source Han Serif SC",monospace;}

javascript:
(function () {
  'use strict';
  // 每页动效。只使用双方共有的 readerTemplate 钩子 API + Web Animations
  // => 同一份主题在我们与 archive 两个引擎上行为一致（互兼容目标）。
  var anims = [], active = null;
  function stop() {
    for (var i = 0; i < anims.length; i++) { anims[i].cancel(); }
    anims = []; active = null;
  }
  function play(node, frames, dur, delay, easing) {
    if (!node || typeof node.animate !== 'function') return;
    anims.push(node.animate(frames, {
      duration: dur, delay: delay || 0, iterations: Infinity, easing: easing || 'ease-in-out'
    }));
  }
  function all(root, sel) {
    return root ? Array.prototype.slice.call(root.querySelectorAll(sel)) : [];
  }
  function start(page) {
    active = page;
    // 小视口不做装饰动效（与 archive 主题同判据，避免小窗下动效抢帧）
    if (readerTemplate.viewport.height <= 440) return;
    var i;

    // 星图：星点闪烁（错相位）+ 边饰起伏 + 标题带轻移
    var stars = all(page, '.sc-art circle');
    for (i = 0; i < stars.length && i < 14; i++) {
      play(stars[i], [{ opacity: 0.3 }, { opacity: 1 }, { opacity: 0.3 }], 2600 + (i % 4) * 700, -i * 210);
    }
    var marks = all(page, '.sc-edge, .sc-footmark');
    for (i = 0; i < marks.length; i++) {
      play(marks[i], [{ opacity: 0.28 }, { opacity: 0.85 }, { opacity: 0.28 }], 4200 + i * 500, -i * 400);
    }
    play(page.querySelector('.sc-band'), [{ transform: 'translateX(0)' }, { transform: 'translateX(6px)' }, { transform: 'translateX(0)' }], 7000);
  }
  // 结算后旧节点可能已脱离文档 => 先停旧动画（换壳/重排后由 motionChange 重新起）
  readerTemplate.on('afterLayout', function () { stop(); });
  readerTemplate.on('motionChange', function (event) {
    if (!event.page || event.state === 'settled' || event.reducedMotion) { stop(); return; }
    if (event.state === 'paused') {
      for (var i = 0; i < anims.length; i++) { anims[i].pause(); }
      return;
    }
    if (active === event.page) {
      for (var j = 0; j < anims.length; j++) { anims[j].play(); }
      return;
    }
    stop(); start(event.page);
  });
  readerTemplate.on('dispose', stop);
})();
